#!/usr/bin/env node
// Guarded diff installer: never switches branches or overwrites a mismatching file.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const patch=Buffer.from('','base64'),files=["app/(tabs)/_layout.tsx", "app/(tabs)/chat/_layout.tsx", "app/(tabs)/home/index.tsx", "app/mental/thoughts/index.tsx", "app/notes/index.tsx", "components/AppFrame.tsx", "components/ArticleCard.tsx", "components/NotificationBell.tsx", "components/PillarUpdates.tsx", "components/UnreadBadge.tsx", "hooks/useNotificationInbox.ts", "hooks/useNotifications.tsx", "lib/daily-thought-notification.ts", "lib/local-progress.ts", "lib/notification-inbox.ts", "package.json", "store/article-store.ts", "store/notification-store.ts", "store/pillar-updates-store.ts", "store/thought-store.ts", "tests/content-sync.cjs", "tests/notification-badges.cjs", "tests/notification-runtime.cjs", "tests/progress-sync.cjs", "tests/ui-contracts.cjs", "types/article.ts"];
function git(args,extra={}){return cp.spawnSync('git',args,{cwd:process.cwd(),encoding:'utf8',maxBuffer:8*1024*1024,...extra})}
function fail(s){console.error(s);process.exit(1)}
const root=git(['rev-parse','--show-toplevel']);if(root.status!==0)fail('Open Git Bash inside TreksorDevCompleto first.');process.chdir(root.stdout.trim());
const remote=git(['remote','get-url','origin']);if(remote.status!==0||!/treksorapp-cmd\/TreksorApp(?:\.git)?\s*$/i.test(remote.stdout))fail('Unexpected repository. Nothing changed.');
if(git(['ls-files','-u']).stdout.trim())fail('An existing merge must be resolved first. Nothing changed.');
for(const file of files){let current=process.cwd();for(const part of file.split('/')){if(part==='..')fail('Invalid path');current=path.join(current,part);if(fs.existsSync(current)&&fs.lstatSync(current).isSymbolicLink())fail('Refusing symlink: '+file)}}
console.log(git(['status','--short','--branch']).stdout.trim());console.log(git(['log','-1','--oneline']).stdout.trim());
const check=git(['apply','--check','--whitespace=nowarn','-'],{input:patch});
if(check.status!==0){if(git(['apply','--reverse','--check','--whitespace=nowarn','-'],{input:patch}).status===0){console.log('Already applied. Nothing changed.');process.exit(0)}console.error(check.stderr);fail('Your local version differs. No files changed. Send this output for an adapted patch.');}
if(!process.argv.includes('--apply')){console.log('CHECK PASSED: '+files.length+' files can be updated. No app files changed. Use --apply to back up and apply.');process.exit(0)}
const backup=fs.mkdtempSync(path.join(path.dirname(process.cwd()),'Treksor-notifications-backup-')),manifest=[];
for(const file of files){const exists=fs.existsSync(file);manifest.push({file,existed:exists});if(exists){const target=path.join(backup,file);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(file,target)}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify({root:process.cwd(),head:git(['rev-parse','HEAD']).stdout.trim(),files:manifest},null,2));
const applied=git(['apply','--whitespace=nowarn','-'],{input:patch});if(applied.status!==0){console.error(applied.stderr);fail('Patch failed. Backup: '+backup)}
console.log('Applied. Backup: '+backup);console.log('Run npm run typecheck and npm run test:notifications, then restart Expo and test on iPhone. No branch switch, merge, dependencies or deployment.');
